def solve(n, edges, s, t):
    import math

    # Initialize adjacency list
    adj = {u: [] for u in range(n)}
    for u, v, w in edges:
        adj[u].append((v, w)]

    # Dijkstra's algorithm for shortest path
    def dijkstra(start, end):
        dist = {node: math.inf for node in range(n)}
        dist[start] = 0
        visited = set()
        priority_queue = [(0, start)]

        while priority_queue:
            current_dist, node = heapq.heappop(priority_queue)
            if node in visited:
                continue
            visited.add(node)
            yield current_dist

            for neighbor, weight in adj[node]:
                if (weight + current_dist) < dist[neighbor]:
                    dist[neighbor] = weight + current_dist
                    heapq.heappush(priority_queue, (dist[neighbor], neighbor)]

        return dist[end]

    # Handle special case
    if s == t:
        return 0

    # Run the algorithm and return result
    return next(dijkstra(s, t), -1)
